import React from "react";
import procedure_image1 from "../Images/procedure_img1.png";
import procedure_image2 from "../Images/procedure_img2.png";
import procedure_image3 from "../Images/procedure_img3.png";
import procedure_image4 from "../Images/procedure_img4.png";
