          <img
            className="img-fluid "
            style={{
              backgroundRepeat: "no-repeat",
              backgroundSize: "cover",
              maxHeight: "100%",
              border:"1px solid black"
            }}
            src={procedure_image3}
            alt="Logo"
          />
